    font-size: 20px;
    background-color: #ccc;
    background-color: #666;
    color: #fff;
    letter-spacing: 3px;
}
.jiezhou-table tr > td:first-child:not(.not-first) {
    width: 60px;
    color: #fff;
    font-weight: 700;
    text-align: center;
    font-size: 20px;
}
.jiezhou-table tr > td:not(:first-child) {
    width: 100px;
    vertical-align: top;
}
.jiezhou-table tr > td:not(:first-child) > p{
    font-size: 11px;
    line-height: 13px;
    text-align: center;
    margin: 3px 0px;
}
.jiezhou-table tr > td.not-first > p{
    font-size: 11px;
    line-height: 13px;
    text-align: center;
    margin: 3px 0px;
